@echo off
chcp 65001 >nul
setlocal enabledelayedexpansion

:: HsMod 备份脚本 — 从当前电脑打包 HsMod 文件
:: 用法：双击运行，或在命令行传入备份目标路径
::   hsmod_backup.bat D:\hsmod_backup

:: 默认备份到当前目录下的 hsmod_backup 文件夹
set "BACKUP_DIR=%~1"
if "%BACKUP_DIR%"=="" set "BACKUP_DIR=%~dp0hsmod_backup"

:: 自动检测炉石安装路径
set "HS_DIR="

:: 方法1：从注册表读取 Battle.net 安装路径
for /f "tokens=2*" %%a in ('reg query "HKLM\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\Hearthstone" /v InstallLocation 2^>nul') do set "HS_DIR=%%b"
if not defined HS_DIR (
    for /f "tokens=2*" %%a in ('reg query "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\Hearthstone" /v InstallLocation 2^>nul') do set "HS_DIR=%%b"
)

:: 方法2：常见默认路径
if not defined HS_DIR (
    if exist "C:\Program Files (x86)\Hearthstone" (
        set "HS_DIR=C:\Program Files (x86)\Hearthstone"
    ) else if exist "C:\Program Files\Hearthstone" (
        set "HS_DIR=C:\Program Files\Hearthstone"
    ) else if exist "D:\Hearthstone" (
        set "HS_DIR=D:\Hearthstone"
    )
)

if not defined HS_DIR (
    echo [错误] 未找到炉石安装目录
    echo 请手动指定路径，例如：hsmod_backup.bat D:\hsmod_backup "C:\Program Files (x86)\Hearthstone"
    pause
    exit /b 1
)

:: 支持第二个参数手动指定炉石路径
if not "%~2"=="" set "HS_DIR=%~2"

echo.
echo  炉石路径: %HS_DIR%
echo  备份目标: %BACKUP_DIR%
echo.

:: 检查关键文件是否存在
set "MISSING=0"
if not exist "%HS_DIR%\BepInEx" (
    echo [警告] BepInEx 文件夹不存在，可能未安装 HsMod
    set "MISSING=1"
)
if not exist "%HS_DIR%\doorstop_config.ini" (
    echo [警告] doorstop_config.ini 不存在
    set "MISSING=1"
)

if "%MISSING%"=="1" (
    echo.
    echo 是否继续？(Y/N)
    set /p "CONFIRM="
    if /i not "!CONFIRM!"=="Y" exit /b 0
)

:: 创建备份目录
mkdir "%BACKUP_DIR%" 2>nul

:: 复制文件
echo 正在备份...

:: BepInEx 整个文件夹
if exist "%HS_DIR%\BepInEx" (
    xcopy "%HS_DIR%\BepInEx" "%BACKUP_DIR%\BepInEx\" /E /I /Y /Q
    echo   [OK] BepInEx\
)

:: doorstop_config.ini
if exist "%HS_DIR%\doorstop_config.ini" (
    copy /Y "%HS_DIR%\doorstop_config.ini" "%BACKUP_DIR%\" >nul
    echo   [OK] doorstop_config.ini
)

:: winhttp.dll (BepInEx 代理入口)
if exist "%HS_DIR%\winhttp.dll" (
    copy /Y "%HS_DIR%\winhttp.dll" "%BACKUP_DIR%\" >nul
    echo   [OK] winhttp.dll
)

echo.
echo ========================================
echo  备份完成！文件保存在: %BACKUP_DIR%
echo ========================================
echo.
echo 把整个 hsmod_backup 文件夹拷到 U 盘，带到新电脑上运行 hsmod_restore.bat 即可。
echo.
pause

